import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Material Multiple Select","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/material-multiple-select.md","filePath":"documentation/field-types/material-multiple-select.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/material-multiple-select.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="material-multiple-select" tabindex="-1">Material Multiple Select <a class="header-anchor" href="#material-multiple-select" aria-label="Permalink to “Material Multiple Select”">​</a></h1><p>The <strong>Material Multiple Select</strong> field type is designed to handle modern, custom dropdown components in web applications that support <strong>multiple selections</strong> (such as tags, chip lists, or checkbox-based dropdown options built with Vuetify, Material-UI, React-Select, PrimeNG, etc.).</p><p>It allows selecting multiple values from a single cell by splitting values with a configurable delimiter (e.g. comma <code>,</code>).</p><img src="/image/image-2.png" alt="Material Multiple Select Options" style="max-width:300px;border-radius:8px;margin:16px 0;"><hr><h2 id="field-options" tabindex="-1">Field Options <a class="header-anchor" href="#field-options" aria-label="Permalink to “Field Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><a href="#separator-to-split-value"><strong>Separator to Split Value</strong></a></td><td>Character used to split multiple values from a single Excel cell (e.g. <code>,</code>, <code>;</code>, <code>|</code>).</td></tr><tr><td><a href="#repeated-dropdown-opening"><strong>If the dropdown has to be opened repeatedly while doing multiple selection, then keep this option on</strong></a></td><td>Automatically reopens the dropdown menu between selections if picking an item closes the popup.</td></tr><tr><td><a href="#match-options-as"><strong>Match options as</strong></a></td><td>Determines how field values are compared against dropdown options (<strong>Equal to Name</strong>, <strong>Search Name in Any Position</strong>, or <strong>Match Name from Start-End Position</strong>).</td></tr><tr><td><a href="#external-library-name"><strong>External Library Name</strong></a></td><td>Select a pre-configured library preset (e.g., MUI, React Select, Chosen). If your library is unlisted, select <a href="#other-material-library">Other Material Library</a>.</td></tr><tr><td><strong>Wait until max options in the dropdown element</strong></td><td>Waits for all option elements to finish rendering in the DOM before matching values.</td></tr><tr><td><strong>Convert the text into lowercase letters and then match the text</strong></td><td>Converts both cell values and option text to lowercase for case-insensitive matching.</td></tr><tr><td><strong>Remove extra space from option text then match the text</strong></td><td>Normalizes multiple consecutive spaces into a single space before comparison.</td></tr><tr><td><strong>Remove all space from option text then match the text</strong></td><td>Strips all spaces from option text before comparison.</td></tr><tr><td><strong>Waiting time after dropdown is open</strong></td><td>Sets a delay (in milliseconds) after opening the dropdown before selecting options.</td></tr><tr><td><a href="#search-and-select"><strong>If this field is to select text after the search</strong></a></td><td>Enables search-and-select workflow: types each keyword into the search input first, then clicks the matching option from the filtered results.</td></tr><tr><td><strong>Before selecting the dropdown option, check that option is already selected?</strong></td><td>Checks whether an option is already selected before clicking it, avoiding accidental unselection.</td></tr><tr><td><strong>Before selecting the dropdown option, uncheck the already selected options</strong></td><td>Clears previously selected items before selecting new ones.</td></tr><tr><td><strong>Trigger event on dropdown matched option</strong></td><td>Dispatches standard DOM events (such as <code>click</code> or <code>change</code>) on each selected option element.</td></tr><tr><td><strong>Trigger event for open dropdown option list</strong></td><td>Dispatches required mouse events to open the dropdown menu.</td></tr><tr><td><strong>After choosing the dropdown option, don&#39;t close the dropdown</strong></td><td>Keeps the dropdown open after all selections are completed.</td></tr></tbody></table><hr><h2 id="separator-to-split-value" tabindex="-1">Separator to Split Value <a class="header-anchor" href="#separator-to-split-value" aria-label="Permalink to “Separator to Split Value”">​</a></h2><p>In bulk automation, multiple target values for a single dropdown are often stored together in one <code>.xlsx</code> Excel column cell.</p><ul><li><strong>Default Separator</strong>: <code>,</code> (Comma)</li><li><strong>Example Cell Value</strong>: <code>Electronics, Home &amp; Kitchen, Sports</code></li><li><strong>Behavior</strong>: The extension parses the string into three distinct values: <ol><li><code>Electronics</code></li><li><code>Home &amp; Kitchen</code></li><li><code>Sports</code> Each value is matched and selected sequentially.</li></ol></li></ul><blockquote><p><strong>Tip:</strong> If your option labels naturally contain commas (e.g., <code>&quot;Washington, D.C.&quot;</code>), change the separator to a semicolon (<code>;</code>) or vertical bar (<code>|</code>) and format your Excel cells accordingly (e.g., <code>Washington, D.C. ; New York, NY</code>).</p></blockquote><hr><h2 id="repeated-dropdown-opening" tabindex="-1">Repeated Dropdown Opening <a class="header-anchor" href="#repeated-dropdown-opening" aria-label="Permalink to “Repeated Dropdown Opening”">​</a></h2><p>Some custom dropdown components automatically close their menu popup immediately after an option is clicked.</p><ul><li><strong>Option Enabled</strong>: If the dropdown closes after selecting the first item, the extension will automatically re-trigger the open action before attempting to match and select the next item.</li><li><strong>Option Disabled</strong>: The dropdown remains open across multiple clicks, allowing the extension to click all matching items in one pass.</li></ul><hr><h2 id="match-options-as" tabindex="-1">Match Options as <a class="header-anchor" href="#match-options-as" aria-label="Permalink to “Match Options as”">​</a></h2><table tabindex="0"><thead><tr><th>Matching Strategy</th><th>Description</th><th>Example Behavior</th></tr></thead><tbody><tr><td><strong>Equal to Name</strong></td><td>Exact match only.</td><td>Value <code>&quot;Tech&quot;</code> matches <code>&quot;Tech&quot;</code> but not <code>&quot;Technology&quot;</code>.</td></tr><tr><td><strong>Search Name in Any Position</strong></td><td>Substring match anywhere in the label.</td><td>Value <code>&quot;Tech&quot;</code> matches <code>&quot;High Tech Gadgets&quot;</code>.</td></tr><tr><td><strong>Match Name from Start-End Position</strong></td><td>Full-string match from start to end.</td><td>Strict label match across the entire element.</td></tr></tbody></table><hr><h2 id="search-and-select" tabindex="-1">Search and Select (Select Text After Search) <a class="header-anchor" href="#search-and-select" aria-label="Permalink to “Search and Select (Select Text After Search)”">​</a></h2><p>For searchable multi-select comboboxes (such as tagging inputs where you must search to filter options):</p><ol><li>Set the field&#39;s <strong>Field Selector Query</strong> to the combobox input element.</li><li>Provide delimited values in your Excel <code>.xlsx</code> sheet (e.g., <code>Apple, Banana, Mango</code>).</li><li>Enable <strong>&quot;If this field is to select text after the search&quot;</strong>.</li><li>For each item: <ul><li>The extension types the keyword into the input box.</li><li>Waits for filtered results to populate.</li><li>Clicks the matching item.</li><li>Clears or resets the search input before typing the next keyword.</li></ul></li></ol><hr><h2 id="external-library-name" tabindex="-1">External Library Name <a class="header-anchor" href="#external-library-name" aria-label="Permalink to “External Library Name”">​</a></h2><p>Predefined drivers are available for:</p><ul><li><strong>Material-UI (MUI)</strong></li><li><strong>React-Select</strong></li><li><strong>Chosen</strong></li><li><strong>Vuetify</strong></li><li><strong>PrimeNG</strong></li><li><strong>Kendo UI</strong></li><li><strong>ng-multiselect-dropdown</strong></li></ul><h3 id="other-material-library" tabindex="-1">Other Material Library <a class="header-anchor" href="#other-material-library" aria-label="Permalink to “Other Material Library”">​</a></h3><p>For unlisted or custom multi-select components:</p><table tabindex="0"><thead><tr><th>Query Field</th><th>Required</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Dropdown Options List Query</strong></td><td><strong>Yes</strong></td><td>CSS selector for option elements in the opened menu.</td><td><code>div.multi-select-menu &gt; div[role=&quot;option&quot;]</code></td></tr><tr><td><strong>Dropdown Open Element Query</strong></td><td>No</td><td>Selector for the button or trigger that opens the menu.</td><td><code>.dropdown-toggle-button</code></td></tr><tr><td><strong>Dropdown Close Element Query</strong></td><td>No</td><td>Selector for closing the dropdown menu.</td><td><code>.backdrop-overlay</code></td></tr><tr><td><strong>Selected Value Element Query</strong></td><td>No</td><td>Selector for the selected chips/tags container.</td><td><code>.selected-chips-container</code></td></tr></tbody></table><hr><h2 id="library-setup-snippets" tabindex="-1">Library Setup Snippets <a class="header-anchor" href="#library-setup-snippets" aria-label="Permalink to “Library Setup Snippets”">​</a></h2><details open="" class="details custom-block"><summary>MUI Multi-Select &amp; Autocomplete</summary><ul><li><strong>Dropdown Options List Query</strong>: <code>ul.MuiAutocomplete-listbox &gt; li[role=&quot;option&quot;]</code></li><li>For checkbox-based selections inside menus: <code>ul.MuiMenu-list &gt; li[role=&quot;option&quot;]</code></li><li>Library reference: <a href="https://mui.com/material-ui/react-autocomplete/#multiple-values" target="_blank" rel="noreferrer">MUI Autocomplete Multi-select</a></li></ul></details><details open="" class="details custom-block"><summary>React Select</summary><ul><li><strong>Dropdown Options List Query</strong>: <code>div[class*=&#39;-menu&#39;] div[class*=&#39;-option&#39;]</code></li><li><strong>Open Trigger</strong>: Trigger JavaScript event <code>[&#39;mousedown&#39;, &#39;click&#39;]</code> on selector <code>div[class*=&#39;-indicatorContainer&#39;]</code>.</li><li>Library reference: <a href="https://react-select.com/home" target="_blank" rel="noreferrer">React Select</a></li></ul></details><div class="warning custom-block"><p class="custom-block-title">Note on Kendo UI</p><p>When automating <strong>Kendo UI</strong> multi-select dropdowns, do not enable the field&#39;s <a href="/documentation/form-fields/field-settings.html#trigger-javascript-event">JavaScript Event</a> option, as Kendo UI manages event bindings internally.</p></div>`,35)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};